using System.Security.Cryptography;
using System.Text.Json;
using Jindan.Contracts;
using Jindan.Desktop;
using Jindan.Infrastructure;
namespace Jindan.Desktop.UiTests;
static partial class Program {
 static async Task MissingModuleCheck(WorkbenchForm main){await Test("real missing Projects DLL leaves native shell project selector readable and Tasks independently usable",async()=>{
  var scratch=Path.Combine(Output,"missing-projects-synthetic-application");Check(!Directory.Exists(scratch),"Missing-module fixture must use fresh output.");Directory.CreateDirectory(scratch);
  var paths=JsonSerializer.Deserialize<string[]>(File.ReadAllText(Path.Combine(Package,"module-inventory.json")))??throw new InvalidDataException("Package inventory missing");var taskRelative=paths.Single(p=>p.Replace('\\','/').EndsWith("/tasks",StringComparison.Ordinal));var source=Path.GetFullPath(Path.Combine(Package,taskRelative));Check(source.StartsWith(Package+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase),"Task fixture source escapes package.");var destination=Path.Combine(scratch,"modules","tasks");Directory.CreateDirectory(destination);var payload=new List<object>();
  foreach(var file in Directory.GetFiles(source,"*",SearchOption.AllDirectories)){Check((File.GetAttributes(file)&FileAttributes.ReparsePoint)==0,"Task fixture cannot follow linked files.");var relative=Path.GetRelativePath(source,file);var target=Path.Combine(destination,relative);Directory.CreateDirectory(Path.GetDirectoryName(target)!);var bytes=File.ReadAllBytes(file);File.WriteAllBytes(target,bytes);var sha=Convert.ToHexStringLower(SHA256.HashData(bytes));Check(Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(target)))==sha,"Task payload copy differs");payload.Add(new{relative,bytes=bytes.Length,sha256=sha});}
  File.Copy(Path.Combine(Package,"trusted-manifests.json"),Path.Combine(scratch,"trusted-manifests.json"));File.WriteAllText(Path.Combine(scratch,"module-inventory.json"),JsonSerializer.Serialize(new[]{"modules/missing-projects","modules/tasks"}));
  // A NEW service instance is essential: the full shell's registration must not hide a missing Projects schema.
  using var reopened=new LocalWorkspace(DataRoot);var actor=await reopened.LoginAsync(UserName,Password);using var catalog=DesktopModules.Load(scratch);Check(catalog.Errors.Count>=1&&catalog.Entries.Count==1&&catalog.Entries[0].Module.ModuleId=="tasks","Missing feature did not fail closed while retaining Tasks");using var shell=new WorkbenchForm(scratch,catalog,new WorkspaceServices(actor,reopened,new ExplicitNoReports()));shell.Show(main);await shell.Ready.WaitAsync(TimeSpan.FromSeconds(10));
  await Throws(()=>reopened.SaveAsync(actor,new(null,"projects",null,0,new(){{"title","Must not save without project schema"}})),"SCHEMA_REQUIRED");Check((await reopened.ListAsync(actor,new RecordQuery("projects"))).Any(r=>r.Id==Ids["p1"]),"Existing authorized project read requires absent schema");shell.SelectProject(Ids["p1"]);Check(shell.SelectedProjectId==Ids["p1"],"Native project selector lost existing project without Projects DLL");Check(Tree(shell).OfType<StatusStrip>().SelectMany(s=>s.Items.OfType<ToolStripStatusLabel>()).Any(s=>(s.Text??"").StartsWith("일부 모듈 차단",StringComparison.Ordinal)),"Native shell does not visibly disclose partially blocked feature");var tasks=await OpenRecord(shell,"tasks");Check(Grid(tasks).Rows.Cast<DataGridViewRow>().Any(r=>r.Tag is WorkRecord w&&w.Id==Ids["publicTask"]),"Independent Tasks native view lost existing task");Capture(shell,"08-missing-projects-native");Samples.Add(new{name="missing Projects native shell",newServiceInstance=true,projectSchemaWriteBlocked=true,existingProjectReadable=true,catalogErrors=catalog.Errors.ToArray(),tasksModuleSource=source,taskPayload=payload,scope="Exact Tasks package copy/trust; absent Projects path. Synthetic existing authenticated store only."});shell.Close();await Until(()=>shell.IsDisposed,"Missing feature shell did not close normally");
 });}
}
